```cpp
int sensorPin = A0;
int viftePin = 9;

void setup() { pinMode(viftePin, OUTPUT);
  Serial.begin(9600);
}

void loop() { int raVerdi = analogRead(sensorPin);
  float spenning = raVerdi * (5.0 / 1023.0);
  float temp = (spenning - 0.5) * 100.0;
  int hastighet = 0;

  if (temp > 25.0) { hastighet = 255;
  } else if (temp >= 20.0) { hastighet = 127;
  } else { hastighet = 0;
  }

  analogWrite(viftePin, hastighet);
  Serial.print("Temp: ");
  Serial.print(temp, 1);
  Serial.print(" °C | Vifte: ");
  Serial.println(hastighet);
  delay(2000);
}
```
